let xs = [2, 4, 6];
assert_eq!(prefix(&xs, 2), &[2,4]);
assert_eq!(prefix(&xs, 99), &xs);
assert_eq!(prefix(&[], 2), &[]);
assert_eq!(prefix(&xs, 2).as_ptr(), xs.as_ptr());
    }
}

