steps.solution:
fn bump(xs: &mut [i32], mid: usize) {
    let mid = mid.min(xs.len());
    let (left, right) = xs.split_at_mut(mid);
    for x in left { *x += 1; }
    for x in right { *x += 10; }
}
fn main() {}

