use std::borrow::Cow;
fn label(s: &str) -> Cow<'_, str> {
    if s.contains('_') { Cow::Owned(s.replace('_', " ")) } else { Cow::Borrowed(s) }
}
fn main() {}

check.tests:
#[cfg(test)]
mod lesson_tests {
    use super::*;
    #[test]
    fn contract() {
assert!(matches!(label("hello"),Cow::Borrowed("hello")));
assert!(matches!(label("a_b"),Cow::Owned(_))); assert_eq!(label("a_b"),"a b"); assert!(matches!(label(""),Cow::Borrowed("")));
    }
}

