    use super::*;
    #[test]
    fn contract() {
assert_eq!(shout(Cow::Borrowed("hi")),"hi!");
assert!(matches!(shout(Cow::Borrowed("hi")),Cow::Owned(_)));
assert_eq!(shout(Cow::Owned(String::from("yes"))),"yes!");
    }
}
